def _kernel(x_ref, z_ref, nw_ref, w_ref, o_ref, h_ref, acc_ref, *, nk, eps):
    j = pl.program_id(1)
    k = pl.program_id(2)

    @pl.when(j == 0)
    def _():
        xf = x_ref[...].astype(jnp.float32)
        zf = z_ref[...].astype(jnp.float32)
        h = xf * (zf * jax.nn.sigmoid(zf))
        var = jnp.mean(h * h, axis=-1, keepdims=True)
        h = h * jax.lax.rsqrt(var + eps)
        h = h * nw_ref[...].astype(jnp.float32)
        h_ref[k] = h.astype(h_ref.dtype)

    d = jnp.dot(h_ref[k], w_ref[...], preferred_element_type=jnp.float32)

    @pl.when(k == 0)
    def _():
        acc_ref[...] = d

    @pl.when(jnp.logical_and(k > 0, k < nk - 1))
    def _():
        acc_ref[...] += d

    @pl.when(k == nk - 1)
    def _():
        if nk == 1:
            o_ref[...] = d.astype(o_ref.dtype)
        else:
            o_ref[...] = (acc_ref[...] + d).astype(o_ref.dtype)


def _pick(n, pref):
